"use client";
// Voice console. Two ways to talk to the lab:
//   - Live voice through Vapi (needs a Vapi public key in the environment).
//   - Typed commands, answered by the same voice tools; the browser can read
//     the answer aloud with its built-in speech synthesis.
// Either way the reply is synthetic speech generated by SI and is labeled so.
// Code generated with SI assistance (Claude Code).

import { useCallback, useEffect, useRef, useState } from "react";
import { ENVIRONMENTS } from "@/lib/environments";
import { COMBUSTION, label, materials } from "@/lib/lab";
import { signal } from "@/lib/activity";
import { fullSnapshot } from "@/lib/controls";
import type { UiAction } from "@/lib/voiceTools";
import { onVoiceToggle, voiceStore } from "@/lib/voiceStore";
import { VoiceOrb, voiceLook } from "./VoiceStage";
import { VoiceWave, type VoiceState } from "./VoiceWave";

interface Line {
  who: "you" | "lab" | "sys";
  text: string;
}

interface VoiceConfig {
  publicKey: string | null;
  assistantId: string | null;
  mcpUrl: string;
  reachable: boolean;
  systemPrompt: string;
  uiTools: { name: string; description: string; parameters: Record<string, unknown> }[];
  dataTools: { name: string; description: string; parameters: Record<string, unknown> }[];
}

const UI_TOOL_NAMES = ["show_environment", "set_atmosphere", "open_panel", "focus_investigation", "filter_tests", "write_brief", "build_chart", "play_video", "watch_nasa_video", "set_controls", "press_control"];

const ENV_WORDS: [RegExp, string][] = [
  [/\b(suit|spacesuit|traje)\b/i, "suit"],
  [/\b(capsule|c[aá]psula)\b/i, "capsule"],
  [/\b(transit|spacecraft|nave)\b/i, "spacecraft"],
  [/\b(station|estaci[oó]n|iss)\b/i, "station"],
  [/\b(rover)\b/i, "rover"],
  [/\b(base|moon|lunar|luna|mars|marte|habitat|h[aá]bitat)\b/i, "base"],
];

const VIEW_WORDS: [RegExp, string, string][] = [
  [/\b(fire|flame|fuego|flama)\b/i, "fire", ""],
  [/\b(scenarios?|simulat(?:or|ion)|escenarios?|simulador|simulaci[oó]n)\b/i, "scenarios", "The fire scenario simulator is on the stage. Choose where the fire starts and what the crew does."],
  [/\b(lab|laboratory|laboratorio|models?|modelos?)\b/i, "lab", "The fire-model lab is on the stage: five models running at this cabin's oxygen and pressure."],
  [/\b(library|resources?|orchestrator|biblioteca|recursos|orquestador)\b/i, "ask", "The library and the orchestrator are on the stage. Ask one question across every source."],
  [/\b(timeline|l[ií]nea de tiempo|cronolog[ií]a)\b/i, "timeline", "The timeline is on the stage: incidents, technology on Earth and the investigations since 1967."],
  [/\b(map|mapa)\b/i, "map", ""],
  [/\b(voice|voz|asistente|assistant)\b/i, "voice", "The voice is on the stage."],
  [/\b(3d|model|modelo|cabin|cabina|drawing|dibujo)\b/i, "environment", "The cabin is on the stage in full size. Drag it to turn it."],
  [/\b(analytics|anal[ií]tica|dashboard|charts?|gr[aá]ficas?)\b/i, "analytics", "The analytics dashboard is on the stage. Describe a chart and it will be added."],
  [/\b(tables?|tests?|records?|tablas?|pruebas?|registros?)\b/i, "tests", "Test records are on the stage. Search them or download the CSV."],
  [/\b(investigations?|investigaciones|investigaci[oó]n)\b/i, "investigations", "All investigations are on the stage, scored for this design."],
  [/\b(materials|materiales)\b/i, "materials", "The materials NASA tested are on the stage."],
  [/\b(connections?|conexi[oó]n|conexiones|nodes?|nodos?|mcp)\b/i, "connections", "The connection map is on the stage. Run a live check to see requests travel."],
];

async function callVoiceTool(name: string, args: Record<string, unknown>): Promise<string> {
  signal("table-voicemcp", "voicemcp-core");
  const r = await fetch("/api/voice/mcp", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ jsonrpc: "2.0", id: 1, method: "tools/call", params: { name, arguments: args } }),
  });
  const j = await r.json();
  const text = j?.result?.content?.[0]?.text ?? "";
  try {
    return JSON.parse(text).say ?? text;
  } catch {
    return text;
  }
}

export function VoiceDock({ o2, psi, onAction, floating, onToggleMode }: { o2: number; psi: number; onAction: (a: UiAction) => void; floating: boolean; onToggleMode: () => void }) {
  const [lines, setLines] = useState<Line[]>([]);
  const [input, setInput] = useState("");
  const [speak, setSpeak] = useState(false);
  const [expanded, setExpanded] = useState(false);
  const [cfg, setCfg] = useState<VoiceConfig | null>(null);
  const [call, setCall] = useState<"idle" | "connecting" | "live">("idle");
  const [level, setLevel] = useState(0);
  const [activity, setActivity] = useState<"none" | "hearing" | "querying" | "speaking">("none");
  const hearingTimer = useRef<number | undefined>(undefined);
  const replyTimer = useRef<number | undefined>(undefined);
  const [lang, setLang] = useState<"en" | "es">("en");
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const vapiRef = useRef<any>(null);
  const handled = useRef(new Set<string>());
  const design = useRef({ o2, psi });
  const logRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    design.current = { o2, psi };
  }, [o2, psi]);
  useEffect(() => {
    fetch("/api/voice/config").then((r) => r.json()).then(setCfg).catch(() => setCfg(null));
    return () => vapiRef.current?.stop();
  }, []);
  useEffect(() => {
    logRef.current?.scrollTo({ top: logRef.current.scrollHeight });
  }, [lines]);

  const add = useCallback((who: Line["who"], text: string) => setLines((l) => [...l.slice(-40), { who, text }]), []);

  const say = useCallback(
    (text: string) => {
      add("lab", text);
      window.clearTimeout(replyTimer.current);
      const done = () => setActivity((a) => (a === "speaking" ? "none" : a));
      setActivity("speaking");
      if (speak && "speechSynthesis" in window) {
        window.speechSynthesis.cancel();
        const u = new SpeechSynthesisUtterance(text);
        u.onend = done;
        u.onerror = done;
        window.speechSynthesis.speak(u);
      } else {
        // Silent reply: show the wave for roughly the time it takes to read it.
        replyTimer.current = window.setTimeout(done, Math.min(6000, 900 + text.length * 22));
      }
    },
    [add, speak],
  );

  // Typed messages. The language model reads the message and operates the lab with the same
  // tools the voice has. Suggestion chips and a missing model key use the local router below.
  async function command(raw: string, local = false) {
    const text = raw.trim();
    if (!text) return;
    add("you", text);
    setInput("");
    signal("you-table");
    setActivity("querying");
    if (!local) {
      try {
        const r = await fetch("/api/command", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ text, state: fullSnapshot() }) });
        const j = (await r.json()) as { say?: string; actions?: UiAction[]; used?: string[]; fallback?: boolean };
        if (!j.fallback && (j.say || j.actions?.length)) {
          for (const a of j.actions ?? []) {
            onAction(a);
            await new Promise((done) => window.setTimeout(done, 220)); // let each step show
          }
          if (j.used?.length) add("sys", j.used.join(" · "));
          return say(j.say || "Done.");
        }
      } catch {
        /* fall through to the local router */
      }
    }
    let { o2: O, psi: P } = design.current;
    try {
      const env = ENV_WORDS.find(([re]) => re.test(text))?.[1];
      const pct = text.match(/(\d+(?:\.\d+)?)\s*(?:%|percent|por ciento)/i);
      const press = text.match(/(\d+(?:\.\d+)?)\s*psi/i);
      const mat = materials().find((m) => text.toLowerCase().includes(m.material.split(" (")[0].toLowerCase().split(" ")[0]));
      const inv = COMBUSTION.find((i) => i.acronym && new RegExp(`(^|[^a-z0-9-])${label(i).replace(/[^a-z0-9]+/gi, "[^a-z0-9]*")}([^a-z0-9-]|$)`, "i").test(text));

      // "chart ... / compare ... / gráfica de ...": build it on the analytics dashboard.
      if (/\b(chart|graph|plot|compare|comparison|dashboard|gr[aá]fica|grafica|compara|comparar)\b/i.test(text) && text.split(/\s+/).length > 2) {
        onAction({ tool: "build_chart", args: { request: text } });
        setActivity("none");
        return add("lab", "Building that chart on the analytics dashboard.");
      }

      // "play the BASS-II video", "video de FLEX": stream footage from NASA.
      if (/\b(videos?|footage|grabaci[oó]n)\b/i.test(text)) {
        if (/sciencecast|youtube|introduc/i.test(text)) {
          onAction({ tool: "watch_nasa_video", args: {} });
          setActivity("none");
          return add("lab", "NASA's ScienceCasts video is open in the library.");
        }
        const withVideo = COMBUSTION.find((i) => i.acronym && new RegExp(`(^|[^a-z0-9-])${label(i).replace(/[^a-z0-9]+/gi, "[^a-z0-9]*")}([^a-z0-9-]|$)`, "i").test(text));
        onAction({ tool: "play_video", args: { investigation: withVideo?.accession ?? "PSI-25", search: "" } });
        setActivity("none");
        return add("lab", `Playing footage from ${withVideo ? label(withVideo) : "BASS-II"}, streamed from NASA.`);
      }

      // History and background: answer from the library of NASA and partner resources.
      if (/\b(apollo|mir\b|spinoff|firefighter|bombero|jaxa|esa\b|history|historia|lessons?|lecci[oó]n|lecciones)/i.test(text)) {
        onAction({ tool: "open_panel", args: { panel: "ask" } });
        return say(await callVoiceTool("search_library", { query: text }));
      }

      // "show me the fire / the tables / the map ...": change the stage and say what it shows.
      const wanted = VIEW_WORDS.find(([re]) => re.test(text));
      const env0 = ENV_WORDS.some(([re]) => re.test(text));
      if (wanted && !env0 && !/\d/.test(text)) {
        onAction({ tool: "open_panel", args: { panel: wanted[1] } });
        if (wanted[1] === "fire" || wanted[1] === "map") return say(await callVoiceTool("check_design", { o2_pct: O, pressure_psi: P }));
        setActivity("none");
        return add("lab", wanted[2]);
      }

      if (/\b(gap|gaps|missing|untested|hueco|huecos|falta)\b/i.test(text)) {
        onAction({ tool: "open_panel", args: { panel: "gaps" } });
        return say(await callVoiceTool("name_the_gaps", { o2_pct: O, pressure_psi: P }));
      }
      if (/\b(brief|report|informe|swarm|analyst|analysts|agentes)\b/i.test(text)) {
        onAction({ tool: "write_brief", args: { question: text } });
        return say("The analysts are writing the brief on screen.");
      }
      if (inv && !env && !pct) {
        onAction({ tool: "focus_investigation", args: { id: inv.accession } });
        return say(await callVoiceTool("explain_investigation", { id: inv.accession }));
      }
      if (mat && !pct && !env) {
        onAction({ tool: "filter_tests", args: { material: mat.material.split(" (")[0] } });
        onAction({ tool: "open_panel", args: { panel: "tests" } });
        return say(await callVoiceTool("check_material", { material: mat.material }));
      }
      if (/\b(rank|ranking|top|best|mejor|mejores)\b/i.test(text) && !env && !pct) {
        onAction({ tool: "open_panel", args: { panel: "ranking" } });
        return say(await callVoiceTool("rank_for_design", { o2_pct: O, pressure_psi: P }));
      }
      if (/\b(how many|numbers|stats|cu[aá]nt)/i.test(text)) return say(await callVoiceTool("lab_numbers", {}));

      if (env) {
        const e = ENVIRONMENTS.find((x) => x.id === env)!;
        O = e.o2_pct;
        P = e.pressure_psi;
        onAction({ tool: "show_environment", args: { environment: env } });
      }
      if (pct || press) {
        if (pct) O = Math.min(100, Math.max(10, +pct[1]));
        if (press) P = Math.min(45, Math.max(3, +press[1]));
        onAction({ tool: "set_atmosphere", args: { o2_pct: O, pressure_psi: P } });
      }
      if (env || pct || press) {
        onAction({ tool: "open_panel", args: { panel: "fire" } });
        return say(await callVoiceTool("check_design", { o2_pct: O, pressure_psi: P }));
      }
      // No structured intent: describe the current design.
      return say(await callVoiceTool("check_design", { o2_pct: O, pressure_psi: P }));
    } catch {
      setActivity("none");
      add("sys", "The lab could not answer that. Check the connection and try again.");
    }
  }

  async function startCall() {
    if (!cfg?.publicKey) return;
    setCall("connecting");
    try {
      const Vapi = (await import("@vapi-ai/web")).default;
      const vapi = new Vapi(cfg.publicKey);
      const dataNames = cfg.dataTools.map((t) => t.name);
      handled.current.clear();
      vapiRef.current = vapi;
      vapi.on("call-start", () => setCall("live"));
      vapi.on("call-end", () => {
        setCall("idle");
        setLevel(0);
        setActivity("none");
      });
      vapi.on("speech-start", () => {
        setActivity("speaking");
        signal("you-vapi");
      });
      vapi.on("speech-end", () => setActivity((a) => (a === "speaking" ? "none" : a)));
      vapi.on("volume-level", (v: number) => setLevel(v));
      vapi.on("error", () => {
        add("sys", "The voice call ended with an error. Typed commands still work.");
        setCall("idle");
      });
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      vapi.on("message", (m: any) => {
        if (m?.type === "transcript" && m.role === "user") {
          // Partial transcripts mean the user is talking right now.
          signal("you-vapi");
          setActivity((a) => (a === "speaking" || a === "querying" ? a : "hearing"));
          window.clearTimeout(hearingTimer.current);
          hearingTimer.current = window.setTimeout(() => setActivity((a) => (a === "hearing" ? "none" : a)), 900);
        }
        if (m?.type === "transcript" && m.transcriptType === "final") add(m.role === "user" ? "you" : "lab", m.transcript);
        if (m?.type === "tool-calls") {
          for (const c of m.toolCallList ?? m.toolCalls ?? []) {
            const name: string = c?.function?.name ?? "";
            const callId: string = c?.id ?? `${name}:${JSON.stringify(c?.function?.arguments ?? "")}`;
            if (handled.current.has(callId)) continue;
            handled.current.add(callId);
            let args: Record<string, unknown> = {};
            try {
              args = typeof c.function.arguments === "string" ? JSON.parse(c.function.arguments || "{}") : (c.function.arguments ?? {});
            } catch {
              continue;
            }
            const ui = UI_TOOL_NAMES.find((n) => name === n || name.endsWith(n));
            signal("vapi-table");
            if (ui) {
              onAction({ tool: ui, args });
              continue;
            }
            if (name === "read_controls" || name.endsWith("read_controls")) {
              // answered here: the page is the only one who knows what is on screen
              vapi.send({ type: "add-message", message: { role: "system", content: `LAB RESULT for read_controls: ${JSON.stringify(fullSnapshot())}` }, triggerResponseEnabled: true });
              continue;
            }
            const data = dataNames.find((n) => name === n || name.endsWith(n));
            if (!data) continue;
            // Fill in the design on the table when the model left it out.
            if (["check_design", "rank_for_design", "name_the_gaps", "swarm_brief"].includes(data) && args.environment == null) {
              args.o2_pct ??= design.current.o2;
              args.pressure_psi ??= design.current.psi;
            }
            setActivity("querying");
            callVoiceTool(data, args)
              .then((result) => {
                setActivity((a) => (a === "querying" ? "none" : a));
                signal("vapi-table");
                add("sys", `${data}: ${result}`);
                vapi.send({ type: "add-message", message: { role: "system", content: `LAB RESULT for ${data}: ${JSON.stringify({ say: result })}` }, triggerResponseEnabled: true });
              })
              .catch(() => {
                vapi.send({ type: "add-message", message: { role: "system", content: `LAB RESULT for ${data}: the lab could not be reached. Tell the user to try again.` }, triggerResponseEnabled: true });
              });
          }
        }
      });

      const model = {
        provider: "openai",
        model: "gpt-4.1",
        messages: [{ role: "system", content: `${cfg.systemPrompt}\n\nThe table currently shows ${design.current.o2}% oxygen at ${design.current.psi} psi.` }],
        tools: [...cfg.uiTools, ...cfg.dataTools].map((t) => ({ type: "function", async: true, function: t })),
      };
      const firstMessage = lang === "es" ? "Laboratorio listo. ¿Qué entorno quieres revisar?" : "Lab is ready. Which environment do you want to look at?";
      const clientMessages = ["transcript", "tool-calls"];
      if (cfg.assistantId) {
        // The saved assistant (scripts/create_vapi_assistant.mjs) already carries the lab's
        // instructions and tools. Only the current table state is passed along.
        await vapi.start(cfg.assistantId);
        vapi.send({ type: "add-message", message: { role: "system", content: `The table currently shows ${design.current.o2}% oxygen at ${design.current.psi} psi.` }, triggerResponseEnabled: false });
      } else {
        await vapi.start({
          name: "Kukulcan Fire Lab",
          firstMessage,
          model,
          voice: { provider: "vapi", voiceId: "Elliot" },
          transcriber: { provider: "deepgram", model: "nova-2", language: lang },
          clientMessages,
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
        } as any);
      }
    } catch {
      add("sys", "Could not start the voice call. Check the Vapi key and microphone permission.");
      setCall("idle");
    }
  }

  function stopCall() {
    vapiRef.current?.stop();
    setCall("idle");
    setActivity("none");
  }

  const lastLab = [...lines].reverse().find((l) => l.who === "lab")?.text;
  const lastYou = [...lines].reverse().find((l) => l.who === "you")?.text;
  const voiceState: VoiceState = activity !== "none" ? activity : call === "connecting" ? "connecting" : call === "live" ? "listening" : "idle";

  // Publish the voice state so the large stage visualizer can follow it, and let it start or end the call.
  useEffect(() => {
    voiceStore.set({ state: voiceState, level, live: call === "live", available: Boolean(cfg?.publicKey), you: lastYou ?? "", lab: lastLab ?? "" });
  }, [voiceState, level, call, cfg, lastYou, lastLab]);
  const toggleRef = useRef<() => void>(() => {});
  useEffect(() => {
    toggleRef.current = () => (call === "idle" ? startCall() : stopCall());
  });
  useEffect(() => onVoiceToggle(() => toggleRef.current()), []);

  const CHIPS = ["Show the rover", "Show the fire", "Play a BASS-II video", "Show the timeline", "What did Apollo 1 teach us?", "Chart extinction by diluent gas", "What about Nomex?", "What is missing?"];
  const talkButton = (extra = "") => (
    <button
      className={`btn flex flex-1 items-center justify-center gap-2 !py-2 ${call === "live" ? "on" : ""} ${extra}`}
      onClick={call === "idle" ? startCall : stopCall}
      disabled={!cfg?.publicKey || call === "connecting"}
      title={cfg?.publicKey ? "Talk to the lab" : "Set NEXT_PUBLIC_VAPI_PUBLIC_KEY to enable live voice"}
    >
      <span className="inline-block h-2 w-2 rounded-full" style={{ background: call === "live" ? "var(--danger)" : "var(--accent)", boxShadow: call === "live" ? "0 0 8px var(--danger)" : undefined }} />
      {call === "idle" ? "Talk to the lab" : call === "connecting" ? "Connecting…" : "End call"}
    </button>
  );
  const conversation = (cls: string) => (
    <div ref={logRef} className={`scroll space-y-1.5 text-[12.5px] leading-snug ${cls}`} aria-live="polite">
      {lines.length === 0 && <div className="text-[11.5px] leading-snug text-faint">Nothing said yet. Talk, or type below: ask for the fire, the tables, a material, an environment, a chart.</div>}
      {lines.map((l, i) => (
        <div key={i} className={l.who === "you" ? "border-l border-accent pl-2 text-accent" : l.who === "sys" ? "pl-2 text-[11.5px] text-faint" : "border-l border-white/40 pl-2"}>
          <span className="mono mr-1.5 text-[9.5px] uppercase tracking-widest text-faint">{l.who === "you" ? "you" : l.who === "lab" ? "lab" : "data"}</span>
          {l.text}
        </div>
      ))}
    </div>
  );
  const chatBox = (placeholder: string) => (
    <form
      className="mt-2 flex gap-2"
      onSubmit={(e) => {
        e.preventDefault();
        command(input);
      }}
    >
      <input className="field min-w-0 flex-1" value={input} onChange={(e) => setInput(e.target.value)} placeholder={placeholder} aria-label="Message for the lab" />
      <button className="btn" type="submit">Send</button>
    </form>
  );
  const modeButton = (
    <button className="mono border border-line px-1.5 py-0.5 text-[9px] uppercase tracking-widest text-dim hover:border-accent hover:text-accent" onClick={onToggleMode} title={floating ? "Dock the voice on the right" : "Shrink the voice to a floating console"}>
      {floating ? "Maximize" : "Minimize"}
    </button>
  );

  // Docked on the right: mostly the voice visual, with the conversation and a chat box under it.
  if (!floating) {
    const look = voiceLook(voiceState);
    return (
      <div className="panel flex h-full min-h-[420px] flex-col p-3">
        <div className="flex items-center gap-2">
          <span className="mono flex items-center gap-2 text-[10.5px] uppercase tracking-[0.2em]" style={{ color: look.css }} role="status">
            <span className="inline-block h-2 w-2 rounded-full" style={{ background: look.css, boxShadow: `0 0 8px ${look.css}` }} />
            {look.label}
          </span>
          <span className="mono ml-auto border border-line px-1.5 py-0.5 text-[9px] uppercase tracking-widest text-dim">SI-generated voice</span>
          {modeButton}
        </div>

        <VoiceOrb className="mt-1 min-h-[180px] flex-[3]" />

        <div className="flex items-center gap-2">
          {talkButton()}
          {!cfg?.assistantId && (
            <button className="btn !px-2 !py-2" aria-pressed={lang === "es"} onClick={() => setLang(lang === "en" ? "es" : "en")} disabled={call !== "idle"} title="Speech recognition language">{lang.toUpperCase()}</button>
          )}
          <button className="btn !px-2 !py-2" aria-pressed={speak} onClick={() => setSpeak(!speak)} title="Read typed answers aloud with the browser voice">Read aloud</button>
        </div>
        {cfg && !cfg.publicKey && <div className="mt-1.5 text-[11px] leading-snug text-dim">Live voice is off: no Vapi key configured. Typed messages use the same tools.</div>}

        <div className="label mt-3">Conversation</div>
        {conversation("mt-1 min-h-[70px] flex-[2] basis-0")}

        <div className="mt-2 flex flex-wrap gap-1">
          {CHIPS.slice(0, 6).map((c) => (
            <button key={c} className="mono border border-line px-1.5 py-0.5 text-[10px] text-dim transition-colors hover:border-accent hover:text-accent" onClick={() => command(c, true)}>{c}</button>
          ))}
        </div>
        {chatBox("Type to the lab")}
      </div>
    );
  }

  // Floating: the compact console, draggable by its header.
  return (
    <div className="panel flex flex-col p-3 shadow-[0_10px_40px_rgba(0,0,0,0.5)]" style={{ background: "rgba(6,12,20,0.96)" }}>
      <div className="-mx-3 -mt-3 flex cursor-grab select-none items-center gap-2 border-b border-line px-3 py-2 active:cursor-grabbing" data-drag-handle title="Drag to move">
        <span className="mono text-[11px] leading-none text-faint" aria-hidden>⋮⋮</span>
        <span className="label">Voice console</span>
        <span className="mono ml-auto border border-line px-1.5 py-0.5 text-[9px] uppercase tracking-widest text-dim">SI voice</span>
        <button className="mono border border-line px-1.5 py-0.5 text-[9px] uppercase tracking-widest text-dim hover:border-accent hover:text-accent" onClick={() => setExpanded(!expanded)} aria-expanded={expanded}>
          {expanded ? "Hide log" : "Show log"}
        </button>
        {modeButton}
      </div>

      <VoiceWave state={voiceState} level={level} />

      <div className="mt-2 flex items-center gap-2">
        {talkButton()}
        <button className="btn !px-2 !py-2" aria-pressed={speak} onClick={() => setSpeak(!speak)} title="Read typed answers aloud with the browser voice">Read aloud</button>
      </div>

      {expanded ? (
        conversation("mt-2 max-h-[26vh] min-h-[90px]")
      ) : (
        // Fixed height so the controls below do not jump when a reply arrives.
        <div className="mt-2 h-[50px] overflow-hidden border-l border-white/40 pl-2 text-[12.5px] leading-snug" aria-live="polite" title={lastLab}>
          {lastLab ? <span className="line-clamp-3">{lastLab}</span> : <span className="text-faint">Ask for the fire, the tables, a material or an environment.</span>}
        </div>
      )}
      {chatBox("Type to the lab")}
    </div>
  );
}
